window.MONSTER_CHUNK_122 = [{"name":"Azizou Demon","cr":4,"xp":1200,"alignment":"CE","size":"Small","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+2 Dex, +6 natural, +1 size","hp":22,"hd":"4d10","hdvalue":4,"fort":1,"ref":6,"will":4,"dr":"5/cold iron","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":15,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"2 claws +8 (1d4+2), bite +8 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 claws, 2d4+3"},{"type":"whisper of madness"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"cause fear"},{"spell":"desecrate"},{"spell":"detect good"},{"spell":"detect thoughts"},{"spell":"invisibility","details":"self only"},{"spell":"scare"},{"spell":"stinking cloud"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 3, 1 azizou 35%"}]}],"strength":14,"dexterity":15,"constitution":11,"intelligence":8,"wisdom":10,"charisma":10,"baseatk":4,"cmb":5,"cmd":17,"feats":[{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":15},{"skill":"Perception","value":11},{"skill":"Stealth","value":13}],"languages":["Abyssal","Common","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary"],"treasure":"none","description_visual":"This small humanoid creature has a jackal-like head, a mouthful of fangs, and large, round eyes with slit-pupils of gray. Its grayish skin is covered in patches of coarse black hair. Membranous wings protrude from its back and its hands and ft. end in sharpened claws.","group":"Demon","source":"Tome of Horrors Complete (3pp)","description":"The azizou is slightly larger than the barizou and is quite strong (for its size). They are relentless combatants and love to inflict pain and suffering on their opponents in combat. The typical azizou stands 3 ft. tall and weighs about 100 pounds.","ecology":"","habitat_society":""},{"name":"Barrow Wight","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":37,"hd":"5d8+15","hdvalue":5,"fort":4,"ref":2,"will":5,"defensive_abilities":["channel resistance +2"],"immunities":["undead traits"],"weaknesses":["resurrection vulnerability"],"speed":[{"type":"land","speed":30}],"melee":"slam +5 (1d4+3 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"energy drain","details":"1 level, DC 14"},{"type":"insanity gaze"}],"strength":14,"dexterity":12,"intelligence":11,"wisdom":13,"charisma":15,"baseatk":3,"cmb":5,"cmd":16,"feats":[{"feat":"Blind-Fight"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":11},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":12},{"skill":"Stealth","value":17}],"languages":["Common"],"sq":[{"type":"create spawn"}],"environments":["any"],"organizations":["solitary","gang (2-5)","pack (6-11)"],"treasure":"standard","description_visual":"This creature appears as a rotting humanoid with leathery, gray skin drawn tight over its frame. Its eyes glow crimson. The creature's clothes appear as rotting and tattered rags.","group":"Wight","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any humanoid creature that is slain by a barrow wight becomes a barrow wight itself in only 1d4 rounds. Spawn so created are less powerful than typical barrow wights, and suffer a -2 penalty on all d20 rolls and checks, as well as -2 hp per HD. Spawn are under the command of the barrow wight that created them and remain enslaved until its death, at which point they lose their spawn penalties and become full-fledged and freewilled barrow wights. They don't possess any of the abilities they had in life."},{"type":"Insanity Gaze","kind":"Su","details":": Anyone with 30 ft. that meets a barrow wight's gaze is affected as if by an insanity spell. A successful DC 14 Will save negates the effect and renders the target immune to the same barrow wight's insanity gaze for 24 hours. The save DC is Charisma-based."},{"type":"Resurrection Vulnerability","kind":"Su","details":"A raise dead spell cast on a barrow wight destroys it (Will negates). Using the spell in this way doesn't require a material component."}],"description":"Barrow wights are undead creatures akin to normal wights, but they are always found in or near barrows, usually guarding the treasure contained therein. They hate living creatures and attempt to destroy anyone who invades their resting place.\n\nA barrow wight is a twisted, insane creature standing about 6 ft. tall.\n\nA barrow wight attempts to use its gaze attack on the closest creature to it when it is first encountered. Creatures not affected by its gaze are pummeled with its fists.","ecology":"","habitat_society":""},{"name":"Basidirond","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"plant","subtypes":["fungus"],"init":1,"senses":[{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":2,"will":2,"immunities":["cold","plant traits"],"weaknesses":["cold vulnerability"],"speed":[{"type":"land","speed":20}],"melee":"slam +7 (1d8+6 plus spores)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hallucination cloud"},{"type":"spores"}],"strength":18,"dexterity":13,"constitution":16,"wisdom":11,"charisma":1,"baseatk":3,"cmb":10,"cmd":21,"cmd_special":"+4 vs. trip","environments":["any underground"],"organizations":["solitary","pair"],"treasure":"incidental","description_visual":"This large creature resembles an inverted umbrella with several stems of dark green or brown hanging beneath it. The inside of its cone-shaped top is inky black.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Cold Vulnerability","kind":"Ex","details":"A basidirond takes no damage from a cold, but is slowed (as the spell) for 1 round per two caster levels. During this time, a basidirond cannot use its spores or hallucination cloud special attacks."},{"type":"Hallucination Cloud","kind":"Ex","details":": As a standard action, a basidirond can release a cloud of invisible spores in a 20-foot radius centered on its form. Creatures within the area must succeed on a DC 15 Fortitude save or be confused for as long as they remain in the cloud plus 1d4 rounds after leaving the area. A new save must be made each round a creature remains within the affected area. The save DC is Constitution-based."},{"type":"Spores","kind":"Ex","details":"A basidirond's slam attack transfers poisonous spores to its opponent. A creature struck must succeed on a DC 15 Fortitude save or these spores take root in his flesh and deal the listed amount of Constitution damage. The save DC is Constitution-based. A remove disease spell cast on an affected character halts the Constitution damage. Basidirond Spores: Disease-contact; save Fort DC 15; frequency 1/round for 5 rounds; effect 1d4 Con damage; secondary effect 1 Con damage; cure 1 save."}],"description":"The basidirond is believed to be related to the ascomoid (see that entry), and like its distant relative, makes its lair in underground natural caverns. Unlike the ascomoid's lair that is usually damp or wet, the basidirond's lair is unusually dry. A basidirond stands about 7 ft. tall. The basidirond attacks by striking with its cone-shaped cap or by firing a line of spores at an opponent. Basidirond Hallucination Cloud Rather than confusing an opponent, you can randomly determine hallucinations for each creature affected. The duration remains the same as detailed under the creature's special attack. BASIDIROND HALLUCINATION CLOUD 1d8 Hallucination 1 Individual believes he is in a swamp and strips off gear and armor to avoid sinking. 2 Individual believes he is being attacked by a swarm of spiders. He attacks the floor and surrounding area. 3 Individual believes item held has turned into a viper; drops item and retreats back from it. 4 Suffocation-Individual believes he is suffocating and gasps for air and clutches throat. 5 Individual believes he has shrunk to 1/10 normal size. He begins yelling for help. 6 Individual believes his associates have contracted a disease. He will not come closer than 10 ft. 7 Individual believes he is melting; grasps self in attempt to hold together. 8 Individual believes his back is covered with leeches. He tears armor, clothing, etc. from his back to get at them.","ecology":"","habitat_society":"","credit":"The Basidirond originally appeared in Dragon #68 (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Blood Bush","cr":4,"xp":1200,"alignment":"N","size":"Small","type":"plant","init":0,"senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+7 natural, +1 size","hp":57,"hd":"6d8+30","hdvalue":6,"fort":10,"ref":2,"will":3,"immunities":["electricity"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"weaknesses":["vulnerable to sonic"],"speed":[{"type":"land","speed":0}],"melee":"tendril +7 (1d4+2)","ranged":"flower dart +5 (1d2+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flower dart"},{"type":"implant"}],"strength":15,"dexterity":10,"constitution":20,"wisdom":12,"charisma":9,"baseatk":4,"cmb":5,"cmd":15,"environments":["temperate forests"],"organizations":["solitary","cluster (2-4)"],"treasure":"none","description_visual":"This creature appears as a 3-foot tall flowering bush with a thick trunk and small whip-like branches. Each branch is topped with a blood-red flower and deep, rich green leaves.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Flower Dart","kind":"Ex","details":"As a standard action, a blood bush can launch a barrage of six flower darts (make an attack roll for each dart). This attack has a range of 40 ft. with no range increment. All targets must be within 30 ft. of each other. The creature can launch only 30 such darts in one day."},{"type":"Implant","kind":"Ex","details":"A creature hit by one of the blood bush's flower darts is implanted with one of its seeds. A seed quickly germinates as follows: Round Effect First DC 18 Will save or flee in fear for 1d6 rounds Third Paralysis for 1d4+2 rounds; DC 18 Fortitude negates Fifth Wounding: 1 point of Constitution damage per minute until the seed is removed or destroyed.A seed can be removed safely up to 5 rounds after implantation with a successful DC 18 Heal check or by cutting it from the victim (dealing 1d2 points of damage); otherwise only a remove disease spell destroys an implanted seed. The save DCs and check DC are Constitution-based."},{"type":"Sonic Vulnerability","kind":"Ex","details":"A blood bush that is subjected to a sonic-based attack or effect (such as a shout spell) loses its blindsight ability and is effectively blinded (as the blindness spell) for a 1d4+6 rounds."}],"description":"The blood bush is a fell plant creature cursed by a wizard in times past. It is named for its blood-red flowers and its thorny blood-red seeds. A blood bush is sometimes referred to as a \"grave marker plant\" because a creature that encounters it, and fails to see the danger this sinister plant presents, rarely lives to tell about it. A blood bush can only be grown from a seed that has germinated inside the warm body of a Small or larger animal. Roots from the germinating seed kill the host and use the nutrients provided to grow rapidly into a deadly plant. A number of nobles use this horrid plant as a deterrent against thieves and robbers, sometimes creating entire hedges of these plants. A blood bush appears as a flowering bush about 3 ft. tall. Its thick trunk quickly splits off into many smaller, whip-like branches, each topped with a blood-red flower surrounded by deep green leaves. Blood bush seeds can be sold for about 20 gp each on the open market; collecting them and living to earn the money they bring isn't the easiest of tasks. When a blood bush detects a warm-blooded creature within 20 ft., it fires a volley of flower darts at the creature, attempting to implant it with its seeds. A creature that dies from the blood bush's seed implantation rapidly decomposes, and a new blood bush springs up in the area within four days. Living creatures within 5 ft. of a blood bush are slashed and cut with its four whip-like tendrils.","ecology":"","habitat_society":""},{"name":"Bloodworm","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"bloodsense","modifier":"120 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+6 natural, -1 size","hp":45,"hd":"6d8+18","hdvalue":6,"fort":8,"ref":2,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":10},{"type":"swim","speed":20}],"melee":"bite +8 (2d6+7 plus bleed)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"}],"strength":21,"dexterity":10,"constitution":17,"wisdom":10,"charisma":2,"baseatk":4,"cmb":10,"cmd":20,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":13}],"environments":["temperate coastlines","any underground","warm coastlines"],"organizations":["solitary","gang (2-5)"],"treasure":"incidental","description_visual":"This creature appears to be a large semi-translucent worm about 15 ft. long. Pale red stripes line its segmented body.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Bloodsense","kind":"Ex","details":"When a bloodworm bites an opponent, it secretes a pheromone that mixes with the blood and that can be detected by other bloodworms to a range of 120 ft. This functions on both land and in water."}],"description":"Bloodworms are carnivorous hunters with voracious appetites, and though not aquatic by nature, prefer a diet of fish, especially smaller sharks and dolphins, shellfish, and the occasional swimmer. Hunting occurs whenever the bloodworm is hungry-day or night.\n\nA bloodworm's lair is beneath the ground, usually in soft earth near the shoreline of lakes and streams. A typical lair is at least as deep as the bloodworm is long and terminates in a large round chamber. Here the bloodworm dine on captured prey and spawn during mating season.\n\nBloodworms mate during the late summer months. Young are born alive and kept wet by secretions from the larger bloodworms as well as water from nearby lakes and rivers. The young don't hunt yet and are cared for by the adults. Within a few months the young are strong enough to fend for themselves and do so, going out on their own.\n\nBloodworms are pale and slightly pink in color. They can grow to a length of 40 ft. or more, though most average about 12-15 ft. long. The red stripes seen along its body are actually a combination of its bodily fluids and the fluids of recently devoured prey flowing through the creature.\n\nA bloodworm lies in wait for its prey, most often just beneath the silt and sand near shorelines. When it detects a potential meal, the bloodworm lunges from its hiding spot, striking with its extended proboscis. Slain prey is dragged into its lair and devoured.","ecology":"","habitat_society":""},{"name":"Bloody Bones","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":42,"hd":"5d8+15 (+5)","hdvalue":5,"fort":6,"ref":2,"will":6,"defensive_abilities":["slippery"],"immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"2 claws +6 (1d6+3)","ranged":"4 tendrils +5 touch (grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pull","details":"tendril, 5ft."},{"type":"tendril"},{"type":"rend","details":"2 claws, 1d6+4"}],"strength":17,"dexterity":12,"intelligence":12,"wisdom":14,"charisma":16,"baseatk":3,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":17,"feats":[{"feat":"Great Fortitude"},{"feat":"Toughness"},{"feat":"Weapon Focus (tendril)"}],"skills":[{"skill":"Climb","value":11},{"skill":"Escape Artist","value":21},{"skill":"Intimidate","value":11},{"skill":"Perception","value":10},{"skill":"Stealth","value":9}],"environments":["any"],"organizations":["solitary","gang (2-5)"],"treasure":"none","description_visual":"This creature appears as a skeletal humanoid with bits of muscle and sinew hanging from its body. Four long, sinewy tendrils writhe from its midsection. The entire creature constantly oozes a mixture of blood and mucus. Its eye sockets are hollow and show no pupils.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Slippery","kind":"Ex","details":"Bloody bones are difficult to grapple or snare due to the constant flow of blood and mucus across their bodies. Webs, magic or otherwise, don't affect bloody bones. Against most other forms of confinement the bloody bones gains a +15 racial bonus to Escape Artist checks."},{"type":"Tendril","kind":"Ex","details":"A bloody bones can fire up to 4 sinewy tendrils from its body at a time, launching them to a range of 30 ft. A bloody bones's attacks with its tendrils resolve as ranged touch attacks. These tendrils are quite strong (10 hp) but can be severed with a slashing weapon or a sunder combat maneuver. Attacking a bloody bones's tendril doesn't provoke an attack of opportunity. If the tendril is currently wrapped around a target, the bloody bones takes a -4 penalty to CMD to resist the sunder attempt. Severing a tendril deals no damage to a bloody bones."}],"description":"Bloody bones are evil undead spirits that haunts caverns, caves, and other desolate places. Their true origins are unknown, but they are believed to be the undead remains of those who desecrate evil temples and are punished by the gods for their wrongdoings.\n\nFrom a distance, they are likely to be mistaken for skeletons, but those that make this mistake often regret it, for the bloody bones is far worse than the undead creature it resembles.\n\nA bloody bones stands about 6 ft. tall. It is unknown if they can speak.\n\nA bloody bones prefers to hide in the shadows and wait for its prey to pass nearby. It then leaps to the attack, entwining its opponents with its tendrils and clawing its prey until dead.","ecology":"","habitat_society":""},{"name":"Boalisk","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"magical beast","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 Dex, +4 natural, -1 size","hp":47,"hd":"5d10+15 (+5)","hdvalue":5,"fort":7,"ref":7,"will":2,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +9 (1d8+7 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+7"},{"type":"gaze"}],"strength":21,"dexterity":17,"constitution":16,"intelligence":1,"wisdom":12,"charisma":4,"baseatk":5,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":24,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":7,"special":"+15 balance"},{"skill":"Climb","value":13},{"skill":"Perception","value":8},{"skill":"Stealth","value":10},{"skill":"Swim","value":13}],"environments":["warm aquatic","warm forests"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a vile serpent with dark scales and reddish eyes.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Gaze","kind":"Su","details":"Those within 30 ft. that meet the boalisk's gaze must succeed on a DC 15 Fortitude save or contract black rot. Black rot-gaze, Fortitude DC 15; onset 1 minute; frequency 1/minute; effect 1d3 Con damage; cure 1 save."}],"description":"Lurking in misty jungles and along dark riverbanks, the boalisk is a vile serpent that can cause death and pestilence with but a gaze. A boalisk is a constrictor snake 12 to 30 ft. long with dark scales interspersed with pale green and yellow daubs of color to help it blend in with its surroundings on the forest floor. The eyes of a boalisk are large and reddish in color.\n\nA boalisk hunts by grabbing prey with its mouth and then squeezing with its powerful body. More powerful opponents (or if the boalisk has recently eaten) will be attacked with the boalisk's gaze attack.","ecology":"","habitat_society":"","credit":"The Boalisk originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Bone Cobbler","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +3 natural","hp":32,"hd":"5d8+10","hdvalue":5,"fort":3,"ref":3,"will":6,"speed":[{"type":"land","speed":30}],"melee":"2 light hammers +7 (1d4+3) or 2 claws +6 (1d3+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"animate bones"},{"type":"bonestripping"},{"type":"breath weapon","details":"60-ft. radius, slow for 1 minute, Fort DC 14, usable every 1d4+1 rounds"}],"strength":16,"dexterity":15,"constitution":15,"intelligence":12,"wisdom":14,"charisma":12,"baseatk":3,"cmb":6,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (light hammer)"}],"skills":[{"skill":"Climb","value":11},{"skill":"Perception","value":10},{"skill":"Stealth","value":10},{"skill":"Survival","value":10}],"languages":["Aklo","Common"],"environments":["any"],"organizations":["solitary","gang (2-5)"],"treasure":"standard","description_visual":"This creature appears as a tattered and desiccated humanoid with grayish flesh drawn tight over its bones. Its eyes are hollow sockets of darkness and its clothes are rags.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Animate Bones","kind":"Su","details":"Once per day, a bone cobbler can animate up to 5 skeletal statues within 30 ft. as a standard action. These creatures fight as skeletons, though their forms and structures don't necessarily have to resemble humanoids (or anything remotely humanoid). This ability otherwise functions similar to an animate dead spell (caster level 7th)."},{"type":"Bonestripping","kind":"Ex","details":"A bone cobbler can rapidly strip all the flesh from a Medium creature in 3 minutes using its claws and hammers. For each size category larger than Medium a corpse is, add 1 minute to the time it takes the bone cobbler to strip the corpse. For each size category smaller than Medium a corpse is, reduce the time by 1 minute (to a minimum of 1 minute). Once stripped, the bone cobbler devours the flesh and collects the victim's bones to use in its \"sculptures\". A creature slain in this manner can only be brought back to life by a miracle, wish, or true resurrection spell."},{"type":"Two-Weapon Fighting","kind":"Ex","details":"In combination with its natural abilities, a bone cobbler's Two-Weapon Fighting feat allows it to attack with both of its weapons at no penalty to attack or damage."}],"description":"The bone cobbler is a tattered and desiccated humanoid and is often mistaken for a zombie at ranges greater than 10 ft. The bone cobbler is a malign and evil creature (thought to be from another plane or dimension of existence) that delights in slaying its opponents and stripping the flesh from their bones. Bone cobblers take the skeletal remains of those they kill and combine them with other bones in their lair. From these bones they sculpt and form weird humanoid or half-humanoid skeletal statues.\n\nBone cobblers stand 6 ft. tall.\n\nThe bone cobbler attacks living creatures with its hammers. Slain creatures are stripped clean, their flesh and muscle devoured by the bone cobbler for sustenance and their bones carted away by the bone cobbler to be used in its abominable creations.","ecology":"","habitat_society":"","gear":"2 light hammers"},{"name":"Bone Swarm","cr":4,"xp":1200,"alignment":"NE","size":"Tiny","type":"undead","subtypes":["swarm"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":27,"hd":"6d8","hdvalue":6,"fort":2,"ref":4,"will":5,"defensive_abilities":["channel resistance +2","swarm traits"],"dr":"5/bludgeoning","immunities":["cold","undead traits","weapon damage"],"speed":[{"type":"land","speed":30}],"melee":"swarm (2d6 slashing and piercing)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 13"}],"strength":15,"dexterity":14,"wisdom":10,"charisma":10,"baseatk":4,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"environments":["any"],"organizations":["any"],"treasure":"none","description_visual":"Tumbling across the floor are the shattered remains of dozens of skeletons: a mass of bone fragments, shards, teeth, and broken skulls.","group":"Swarm","source":"Tome of Horrors 4 (3pp)","description":"A bone swarm is created when multiple animated skeletons are destroyed more or less simultaneously, either through a single powerful area attack or by simply being smashed to pieces in melee. The bones of the skeletons are scattered and smashed, but the necromantic magic that animated them lingers on, pulling the bones back together in a mass of clattering fragments.\n\nA bone swarm is ten ft. across and is comprised of hundreds of bones and bone shards. When it forms to attack, it appears as a roiling mass of bone shards.","ecology":"","habitat_society":""},{"name":"Bunyip","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"magical beast","subtypes":["aquatic"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"keen scent"},{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural","hp":42,"hd":"5d10+15","hdvalue":5,"fort":7,"ref":7,"will":3,"speed":[{"type":"swim","speed":50}],"melee":"bite +8 (2d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"frenzy"},{"type":"roar"},{"type":"vorpal bite"}],"strength":14,"dexterity":16,"constitution":17,"intelligence":2,"wisdom":11,"charisma":7,"baseatk":5,"cmb":7,"cmd":20,"feats":[{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":11}],"environments":["temperate aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This aquatic creature resembles a cross between a seal and a shark.  Its front half is that of a black seal while its rear section is that of a grayish-black shark.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Frenzy","kind":"Ex","details":"A bunyip that detects blood in the water goes into a killing frenzy, as do all other bunyips within a 90-foot radius. Frenzied bunyips attack until either they or their opponents are dead. A frenzied bunyip can make one extra attack when making a full attack action. The attack is made using the creature's full base attack. Additionally, it gains a +1 bonus on attack rolls and a +1 dodge bonus to AC and Reflex saves (none of which are included in the statistic block above). A frenzied bunyip's swim speed increases by 10 ft. (to 60 ft.). This frenzy lasts for 1 minute (10 rounds) and can only be used once per encounter."},{"type":"Keen Scent","kind":"Ex","details":"Bunyips can notice creatures by scent in a 90-foot radius and detect blood in the water at ranges of up to one-half mile."},{"type":"Roar","kind":"Su","details":"When a bunyip roars, all creatures with 4 or less HD within a 100-foot spread must succeed on a DC 15 Will save or become panicked for 2d4 rounds. This is a sonic, mindaffecting fear effect. Whether or not the save is successful, an affected creature is immune to the roar of that bunyip for one day. The save DC is Constitution-based."},{"type":"Vorpal Bite","kind":"Ex","details":"If a bunyip scores a natural 20 on its attack roll and confirms the critical hit, it severs one of the opponent's extremities (roll 1d6: 1-3 arm, 4-6 leg; 50% chance of either right or left)."}],"description":"The bunyip is about 6 ft. long, though specimens of up to 10 ft. long have been encountered.\n\nBunyips don't attack creatures larger than themselves, except in self-defense or if they detect blood in the water. They begin combat using their powerful roar and then bite opponents who don't succumb to the fear-inducing effects of their roar.","ecology":"","habitat_society":"","credit":"The Bunyip originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Caterwaul","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"magical beast","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":16,"ac_flat_footed":12,"ac_mods":"+6 Dex, +2 natural","hp":37,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":10,"will":3,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":50},{"type":"climb","speed":20}],"melee":"bite +8 (1d6+2 plus grab), 2 claws +8 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws, 1d4+2"},{"type":"screech"}],"strength":14,"dexterity":22,"constitution":15,"intelligence":7,"wisdom":14,"charisma":6,"baseatk":5,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":23,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite, claws)"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 balancing, +18 jumping"},{"skill":"Climb","value":14},{"skill":"Escape Artist","value":7},{"skill":"Perception","value":13},{"skill":"Stealth","value":14,"special":"+26 in tall grass"}],"sq":[{"type":"sprint"}],"environments":["temperate forests","temperate mountains"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This creature appears to be a feline-like elf with yellow eyes, dark blue fur, and a long swishing tail.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Evasion","kind":"Ex","details":"This functions identically to the rogue ability."},{"type":"Screech","kind":"Su","details":"Once every 10 minutes, a caterwaul can emit a piercing screech that deals 1d8 points of sonic damage to all creatures within 60 ft. that hear it. A creature that makes a successful DC 16 Fortitude save takes no damage. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Sprint","kind":"Ex","details":"Once per minute, a caterwaul can move four times its normal speed (200 ft.) when it makes a charge."}],"description":"Caterwauls are semi-intelligent bipedal felines that possess great speed. They are natural predators and use their speed to stalk prey. The caterwaul's lair is most often a cave littered with sticks, twigs, and leaves, with walls covered in scratch marks where the beast has honed its claws.\n\nA caterwaul is about 6 ft. long (or tall if on two legs). It weighs about 250 pounds.\n\nA caterwaul begins combat by utilizing its screech attack. After that, it uses its claw and bite attacks each round. By dropping to all fours, it can increase its movement speed.","ecology":"","habitat_society":"","credit":"The Caterwaul originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Cave Troll","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["giant"],"init":6,"senses":[{"type":"darkvision","modifier":"90 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":22,"ac_touch":17,"ac_flat_footed":15,"ac_mods":"+6 Dex, +1 dodge, +5 natural","hp":52,"hd":"5d8+30","hdvalue":5,"hp_mods":["regeneration 3 (fire or acid)"],"fort":9,"ref":10,"will":0,"speed":[{"type":"land","speed":60},{"type":"climb","speed":20}],"melee":"2 claws +6 (1d4+2), claw (from haste) +6 (1d4+2), and bite +6 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d4+3"}],"strength":15,"dexterity":22,"constitution":20,"intelligence":6,"wisdom":9,"charisma":6,"baseatk":3,"cmb":5,"cmd":22,"feats":[{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":7}],"languages":["Giant"],"sq":[{"type":"haste"},{"type":"spider climb"}],"environments":["any underground"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This ugly humanoid appears to be about 6 ft. tall. Its leathery skin is blackish-gray and its eyes are yellow. It has long, upright ears, almost elven in nature. Its arms and legs are long and slender and end in wicked-looking claws.","group":"Troll","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Haste","kind":"Su","details":"A cave troll is affected by a permanent haste spell (caster level 8th). This grants the cave troll a +1 bonus on attack rolls, and a +1 dodge bonus to AC and Reflex saves (both already figured into the stat block above). Any condition that makes the cave troll lose its Dexterity bonus to AC also makes it lose its dodge bonus. This is an inherent bonus and cannot be dispelled or negated. When making a full attack action, a cave troll can make one extra attack with any weapon it is holding or one extra claw attack (if using natural weapons). The extra attack is at the cave troll's full attack bonus."},{"type":"Spider Climb","kind":"Su","details":"A cave troll can climb sheer surfaces as though by a spider climb spell (caster level 4th). This ability is always active, but can be negated or dispelled. The cave troll can restart it again on its next turn as a free action."}],"description":"Cave trolls are smaller cousins of the normal troll and are found in all types of subterranean realms. They are as deadly, or more so, than their larger brethren. Cave trolls have the same voracious appetite of the normal troll and sustain themselves on whatever they can find in their Underdark realms. They rarely venture to the surface world, preferring the security and tranquility of the darkness they inhabit. If extremely hungry or if food is scarce, however, a cave troll ventures to the surface and attacks whatever it finds near its lair. Cave trolls stand 6 ft. tall and weigh 300 pounds. Cave trolls don't walk with the same hunched gait of their larger relatives. They stand upright and move with blinding speed. Cave trolls often use deception when they first encounter prey, especially intelligent prey. Their troll heritage often leads to the misconception that they are slow in combat, which they gladly allow their opponents to believe - until the cave troll strikes or moves. Only then is the ruse negated and the true nature of the troll revealed. Cave trolls attack by grabbing and rending an opponent.","as_character":[{"description":"Cave troll characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Strength, +12 Dexterity, +10 Constitution, -4 Intelligence (minimum 3), -2 Wisdom, -4 Charisma."},{"type":"Base speed","value":"A cave troll's base land speed is 60 ft. Its permanent spider climb ability gives it a climb speed of 20 ft."},{"type":"Darkvision","value":"Cave trolls can see in the dark out to 90 ft."},{"type":"Low-light vision","value":"Cave trolls can see twice as far as humans in conditions of dim light."},{"type":"Scent","value":"Cave trolls can detect opponents within 30 ft. by sense of smell."},{"type":"Racial Hit Dice","value":"A cave troll begins with four levels of humanoid, which provide 4d8 Hit Dice, a base attack bonus of +3, and base saving throw bonuses of Fort +4, Ref +1, and Will +1."},{"type":"Racial Skills","value":"A cave troll's humanoid levels give it skill points equal to 4 x (2 + Int modifier, minimum 1)."},{"type":"Racial Feats","value":"A cave troll's humanoid levels give it two feats."},{"type":"AC","value":"+5 natural armor bonus."},{"type":"Natural Weapons","value":"Cave trolls fight with 2 claws (1d4) and a bite (1d6)."},{"type":"Special Attacks","value":"Rend."},{"type":"Special Qualities","value":"Haste, regeneration 3 (fire or acid), spider climb."},{"type":"Languages","value":"Cave trolls begin play speaking Giant. Cave trolls with high Intelligence scores can choose from the following languages: Common, Orc."}]}],"ecology":"","habitat_society":""},{"name":"Cavern Crawler","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 natural","hp":51,"hd":"6d10+18","hdvalue":6,"fort":8,"ref":7,"will":3,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +11 (1d8+6 plus disease)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":6,"cmb":10,"cmd":22,"cmd_special":"+12 vs. trip","feats":[{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Perception","value":10}],"environments":["any underground"],"organizations":["solitary","gang (2-5)","swarm (6-12)"],"treasure":"none","description_visual":"This creature appears to be a wild mix of giant centipede and slate gray reptile.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Cavern Sickness: Bite-injury; save DC 16 Fort; onset 1 minute; frequency 1 day; effect 1d2 Str damage and -2 penalty on all attack rolls, checks, and saves while underground; cure 2 consecutive saves. Note: Failing two consecutive saves results in the victim being affected as if by a confusion spell for the duration of the disease. The save DC is Constitution-based."}],"description":"Cavern crawlers are subterranean creatures that make their lairs in narrow pits and shafts, feeding on cave rats, monstrous centipedes and spiders, and other such underground denizens. They are feared by subterranean dwellers for their toxic bite which causes its victims to become delusional or lost in deep dark cavern recesses.\n\nCavern crawlers lair in areas where food is plentiful; when their source of food runs out, they move the entire lair to a new area, digging new tunnels and chambers as needed by the nest. A cavern crawler can go roughly a week without food before it begins to exhibit signs of starvation. Many resort to cannibalism before that happens however. A cavern crawler nest consists of a single female and several male workers and soldiers. The workers hunt for and supply needed food for the nest while the soldiers guard the female and young. The female lays 10-20 eggs at one time which are buried beneath the ground in a special chamber dug off the main chamber of the lair. Eggs hatch 60-90 days after incubation and young reach maturity in about 12 months.\n\nA cavern crawler has a reptilian head similar to that of an iguana and eighteen short clawed legs on each side of its body which allows it to climb on any rocky surface with ease. Its body is slate gray and lighter on the underside. Its legs are covered in short bristles of dark gray or black. A typical cavern crawler can reach lengths of 6 ft. or more. Some species up to 12 ft. long are rumored to have been encountered by unsuspecting adventurers, but these reports have yet to be confirmed.\n\nA cavern crawler attacks from ambush, clinging to stalactites or overhangs and dropping on its unsuspecting prey. The target is subjected to repeated bites and dragged to a safe place before being devoured by the cavern crawler.","ecology":"","habitat_society":""},{"name":"Cavern Lizard","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+2 Dex, +5 natural, -1 size","hp":42,"hd":"5d10+15","hdvalue":5,"fort":7,"ref":6,"will":4,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"bite +10 (2d6+7 plus grab)","space":"10 ft.","reach":"5 ft.","strength":20,"dexterity":15,"constitution":17,"intelligence":3,"wisdom":12,"charisma":2,"baseatk":5,"cmb":11,"cmd":23,"cmd_special":"+4 vs. trip","feats":[{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Perception","value":9},{"skill":"Stealth","value":10,"special":"+14 in areas of natural stone or rock"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"50% standard","description_visual":"A 10-foot long gray lizard with large wide ft. and sapphire-gold bulging eyes stares. Balanced upon thick and muscled, its feet cling to surfaces upon small suction cup-like pads. Its head is angular and somewhat flat and its mouth sports a row of long, serrated teeth.","group":"Lizard","source":"Tome of Horrors Complete (3pp)","description":"These large magical lizards, readily identified by large bulging sapphirecolored eyes, are found only in the darkest underground places and never venture to the surface world.\n\nA cavern lizard is typically very aggressive and often travels far away from its lair in order to hunt. While not territorial, a cavern lizard is rarely encountered with others of its kind. Each cavern lizard often has a hunting ground covering up to 2 miles in the Under Realms.\n\nA cavern lizard's lair is a large expanse of interconnected caves littered with the bones and scattered remains of its victims (including treasure). Hunting cavern lizards usually drag their kill back to their lair before devouring it. If young are present in the lair, the kill is divided between them. Young cavern lizards resemble their adult counterparts in all respects, save their eyes are a dull blue. During mating season (late summer, early fall) 1d6 eggs may be found in the lair. Eggs are round in shape, leathery to the touch, and gray in color.\n\nCavern lizards are aggressive ambush hunters. They prefer to scale the walls and wait for prey to pass underneath them where they drop down on their unsuspecting meal. In most battles, once a cavern lizard bites, it hangs on until its opponent is dead. If facing more than one foe, it won't employ this tactic so as not to leave itself defenseless against other aggressors. If cornered or extremely hungry, a cavern lizard fights to the death; otherwise it retreats if it is facing a particularly powerful opponent.","ecology":"","habitat_society":""},{"name":"Chrystone","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"-1 Dex, +6 natural","hp":42,"hd":"4d10+20","hdvalue":4,"fort":1,"ref":0,"will":3,"defensive_abilities":["shatter weapons"],"dr":"5/-","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":20}],"melee":"longsword +7 (1d8+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"stone shape","details":"item of 5 pounds or less, otherwise as the spell"}]},{"frequency":"2/day","spells":[{"spell":"stone tell"}]},{"frequency":"3/day","spells":[{"spell":"color spray"}]}],"strength":17,"dexterity":9,"intelligence":8,"wisdom":11,"charisma":1,"baseatk":4,"cmb":7,"cmd":16,"feats":[{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":4}],"environments":["any"],"organizations":["solitary","company (2-6)","squad (7-20)"],"treasure":"standard","description_visual":"This creature appears as a statue constructed of rock and crystal. It has almost no neck; its head seems attached firmly to its shoulders, though by observing it, you see that it is able to turn its head freely. Each of its hands has two fingers and two opposable thumbs.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Ex","details":"When a chrystone is destroyed, it shatters, spraying razor-sharp fragments from its form. Creatures within 5 ft. of the chrystone take 2d6 points of damage. A DC 12 Reflex saving throw halves the damage. A chrystone can prevent itself from shattering by making a DC 12 Will save as it is destroyed."},{"type":"Spell-like Abilities","kind":"Sp","details":"Three times per day, a chrystone can use its stone shape to repair itself, healing 1d6 points of damage per use. This requires a full-round action that provokes attacks of opportunity. The save DC for the chrystone's color spray includes a +2 racial bonus."},{"type":"Immunity to Magic","kind":"Ex","details":"A chrystone is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A transmute rock to mud spell slows a chrystone (as the slow spell) for 2d6 rounds, with no saving throw, while transmute mud to rock heals all of its lost hit points. A stone to flesh spell doesn't actually change the chrystone's structure but negates its damage reduction and immunity to magic for 1 full round."},{"type":"Shatter Weapons","kind":"Ex","details":"Whenever a character strikes a chrystone with a weapon (magical or nonmagical), the weapon must succeed on a DC 14 Fortitude save or shatter into pieces. A magic weapon uses its own save bonus or that of the wielder, whichever is higher. If the weapon breaks, the chrystone takes no damage from the attack. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"Chrystones are creatures made of rock and crystal that normally stand just over 5 ft. tall. Their coloration varies by the types of crystal and rock they absorb, giving each chrystone a unique pattern of striations and coloration that makes them easy to tell apart. Originally imbued with life by a spellcaster in a ritual involving the blood of several dragons and a demon, chrystones grow new offspring through budding. To form a new bud, a chrystone must consume several times its weight in crystals and consume at least 300 gp worth of gems. The bud continues to grow from the chrystone's back until it is large enough to separate. Each chrystone offspring retains the memories and knowledge of its entire parental line. Chrystones were originally created to be part of an army, but those plans were cut short by their creator's death. As they developed and spread, they became more free-willed and independent and wished to make certain they were never enslaved again. They retain all of the abilities that would have made them a powerful army, and their racial knowledge helps them put these abilities to the best possible use. Chrystones, while usually neutral, have a racial memory of being slaves to the whim of their creator. This memory makes them somewhat paranoid when dealing with other races, making them more likely to attack other races than talk with them. Chrystones open with color spray which emanates from their mouth like a breath weapon and then close for melee combat if targets are close enough; otherwise, they stand back and fight with their longswords. If a battle is going poorly, a chrystone attempts to retreat and ambush its opponents when it has repaired itself. Construction A chrystone's body is chiseled from a single block of hard stone, such as granite, weighing at least 1,000 pounds. The stone must be of exceptional quality, and costs 1,000 gp. CHRYSTONE CL 14th; Price 16,000 gp Requirements Craft Construct, color spray, limited wish, polymorph any object, shatter, stone shape, stone tell, creator must be caster level 14th level; Skill Craft (sculptures) or Craft (stonemasonry) DC 15; Cost 8,500 gp","ecology":"","habitat_society":"","credit":"The Chrystone first appeared in the Necromancer Games module Hall of the Rainbow Mage by Patrick Lawinger (©2002, Necromancer Games, Inc.)."},{"name":"Cimota","cr":4,"xp":1200,"alignment":"LE","size":"Medium","type":"undead","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense"}],"auras":["unnatural aura (30 ft.)"],"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+5 natural, +3 Dex","hp":47,"hd":"5d8+25","hdvalue":5,"fort":6,"ref":4,"will":6,"defensive_abilities":["channel resistance +2","displacement","unholy existence"],"immunities":["cold","electricity","undead traits"],"sr":12,"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 claws +6 (1d6+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"manifestation"}],"strength":16,"dexterity":16,"intelligence":14,"wisdom":14,"charisma":21,"baseatk":3,"cmb":6,"cmd":19,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Diplomacy","value":10},{"skill":"Fly","value":7},{"skill":"Intimidate","value":13},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":11}],"languages":["Common","Infernal"],"environments":["any"],"organizations":["solitary","pair","haunt (3-6)"],"treasure":"standard","description_visual":"A figure materializes out of the surrounding shadows. It has the black cloak and cowl of a monk, floating in the air with no visible body. Menacing green eyes glare from inside the dark hood.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Displacement","kind":"Su","details":"Cimota manifest on the Prime Material Plane as a shifting cloud of shadows that coalesce into their cloaked and hooded forms. On any round that a cimota first manifests, its shifting forms affect it as a displacement spell. Attacks on a cimota at this time have a 50% miss chance as if the cimota had total concealment. Unlike actual total concealment, this displacement doesn't prevent enemies from targeting a cimota normally. This effect is canceled one round after a cimota manifests, or if a cimota takes any action in its new locale."},{"type":"Lifesense","kind":"Su","details":"A cimota notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Manifestation","kind":"Su","details":"As a standard action, a cimota can transport itself via planar travel from any point on the Prime Material Plane to another point within its defined area, or within 300 ft. of the artifact to which it is bound. A cimota may also lurk on the Negative Material Plane, prepared to manifest on the Prime Material if certain conditions are met, such as trespassers entering the area they are doomed to guard. A cimota cannot attack or move in the same round in which it manifests, although it may manifest as partial surprise action before initiative. A cimota benefits from displacement on the round in which it first manifests."},{"type":"Unholy Existence","kind":"Su","details":"Although it is possible to temporarily destroy a cimota's physical form, it will return in 1d6 days, manifesting again to continue its unholy existence. The only way to permanently destroy a cimota is to disrupt its existence by consecrating the ground to which it is tied or the destruction of the artifact to which it is bound. Sometimes, significant alteration of an unholy place, such as demolition of an evil temple or burning a haunted forest, could cause cimota to fade away permanently. Although their physical forms may be damaged by normal attacks, their unholy existence grants them SR 17. Because cimota exist partially on the Negative Material Plane they are subject to banishment or other spells that affect outsiders."},{"type":"Unnatural Aura","kind":"Su","details":"Animals don't willingly approach within 30 ft. of a cimota unless a master makes a DC 25 Handle Animal, Ride, or wild empathy check. This aura takes effect when a cimota manifests on the Prime Material Plane. Animals that come within 30 ft. of a place where cimota are lurking on the Negative Material Plane, or an artifact to which a cimota is bound; Will be uneasy and show signs of disquiet."}],"description":"Cimota are the physical manifestations of evil thoughts and actions. They exist on the Negative Material Plane, manifesting in the Prime Material as cloaked figures. Their existence is always tied to a specific area or artifact that is imbued with ancient and highly malevolent evil. A cimota is able to manifest itself anywhere within an accursed locale that has given it life, or within 300 ft. of an evil artifact to which it is attached.\n\nThe physical form of a cimota is a floating figure in a monk's cassock. Green eyes glow deep within their raised cowls, but their bodies are entirely invisible. See invisibility, true sight, or some similar ability to see invisible objects will reveal a ghostly, black human figure within the cimota's cloak. Cimota are manifestations of evil that may be touched like any other creature. They take damage from normal weapons. Their unnatural existence allows them to fly on the Prime Material Plane just like an incorporeal creature, except that they cannot pass through solid objects. When a cimota is destroyed in combat only a few shreds of tattered black cloth remain to show that they ever existed.\n\nCimota are bound to repeat the evil thoughts and actions that created them. When they manifest they will endlessly repeat the deeds that spawned them. So, for instance, a group of cimota may haunt a ruined temple, re-enacting evil rituals. Cimota may guard an unholy site such as a city, forest or building. They will fight to the death to defend these places. Cimota who are bound to an artifact may act out the intentions of that artifact. A cimota might follow the owner of an artifact, for instance, slaying the owner's friends and associates while keeping its existence a secret. Within the parameters of their creation, cimota are capable of strategy, deception and intelligent tactics.\n\nCimota are created by evil energy. Their supernatural nature gives them the ability to fight with two fists or two weapons without penalty, each attack landing with the force and accuracy of a single weapon attack. Cimota attacks are either a rake of invisible claws or a blow from a fist. They are capable of delivering slashing or bludgeoning blows as needed.\n\nCimota are capable of speaking Common and Infernal. Their voices are either hollow, ringing and unnatural, or malevolent whispers. Most often cimota use their voices to chant or to shout out dire condemnations at intruders. They don't parley and they never negotiate unless it is to deceive mortals to their deaths.","ecology":"","habitat_society":"","credit":"Original author Mark R. Shipley  Originally appearing in The Black Monastery (© Frog God Games/ Mark R. Shipley, 2011)"},{"name":"Clamor","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"aberration","subtypes":["extraplanar","incorporeal"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":20,"ac_flat_footed":13,"ac_mods":"+3 deflection, +7 Dex, +0 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":4,"ref":10,"will":5,"defensive_abilities":["natural invisibility"],"weaknesses":["sound-related vulnerabilities"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"speed_mod":"speed of sound","ranged":"sonic ray +10 touch (2d6 sonic)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sonic burst SQ sound mimicry"}],"dexterity":25,"constitution":17,"intelligence":5,"wisdom":12,"charisma":17,"baseatk":3,"cmb":3,"cmd":23,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Fly","value":20},{"skill":"Perception","value":5,"special":"+13 to detect noises"}],"languages":["uncertain","seems to understand some Common and a smattering of most other languages"],"environments":["any land"],"organizations":["solitary"],"treasure":"none","description_visual":"A series of garbled voices, clicks, grinding noises, and other less discernible sounds seem to emanate from empty air, with no obvious point of origin.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Natural Invisibility","kind":"Su","details":"As creatures of living sound, a clamor is naturally invisible, even when it attacks. This ability is inherent and isn't subject to the invisibility purge spell."},{"type":"Sound Mimicry","kind":"Ex","details":"A clamor can duplicate any sound it has ever encountered with perfect accuracy as a free action. It can use this ability to duplicate speech, music, or any other auditory phenomenon, although sounds with magical properties (such as power word spells) lose their magical effects when duplicated."},{"type":"Sonic Burst","kind":"Ex","details":"A clamor can emit a massive onslaught of sonic energy as a full-round action that can be heard for miles in all directions. Any living creature within 100 ft. of the clamor must make a successful DC 15 Fortitude save or be stunned for 1d3 rounds. Furthermore, living creatures within 50 ft. of the clamor must make a successful DC 15 Fortitude save or be permanently deafened. A restoration, wish, miracle, or remove blindness/deafness spell restores hearing and negates the stunning effect. The save DCs are Constitution-based."},{"type":"Speed of Sound","kind":"Ex","details":": Once per day, a clamor can move at the speed of sound for a number of minutes equal to its Hit Dice. Its fly speed increases to 6,820 ft. (34,100 squares), but it cannot attack or use of any of its other abilities when moving this way."},{"type":"Sound-Related Vulnerabilities","kind":"Ex","details":"Any magical silence effect or effect that creates a vacuum deals 3d6 points of damage to a clamor and forces it to make a successful Fortitude save (DC equal to 10 + spell level + spell caster's appropriate ability score modifier) or become panicked for 1 minute. In addition, the following spells can affect a clamor in unusual ways. Ghost sound, major image, minor image, message, ventriloquism, whispering wind: These magically generated + spell level + the caster's appropriate ability score modifier) or act as though affected by a confusion spell for a number of rounds equal to the caster's level. Sculpt sound: If targeted directly at the clamor, this spell deals 1d4 points of damage per caster level. The clamor is allowed a Fortitude save for half damage. Alternately, a bard (and only a bard) using sculpt sound can attempt to completely control the actions of a clamor. The clamor is allowed an initial Fortitude save to negate the effect; if it fails, it is controlled as if by a dominate monster spell with a caster level equal to that of the bard's class level. Shout, sound burst: These spells do no damage to a clamor, but force it to make a Will save or be affected as if by a charm monster spell with a caster level equal to that of the caster."}],"description":"Clamors have a playful kind of intelligence, and they appear to desire communication. Being able to mimic any sound they have ever encountered, clamors wander the Material Plane emitting a nonsensical cacophony of voices, crashes, clicks, roars, and music. Since they are usually invisible, most adventurers that encounter a clamor walk away from the creature without ever having realized that they had met one.\n\nMany a sentry on duty has heard only his own voice in response to what he thought was someone walking around out in the darkness; what he really heard was a clamor trying to talk to him.\n\nBards are fascinated by these odd creatures, and many a bard has gained a clamor as a companion of sorts. They have intelligence, and can be trained. A bard of at least 5th level that has had prior contact with a clamor is capable of communicating with these creatures on a rudimentary basis.\n\nThe intelligence of a clamor is just barely above that of a small child, so complex communication is out of reach.\n\nClamors tend to keep at a distance, emitting random noises and \"playing back\" any interesting sound made by the creatures they are observing.\n\nOnce provoked to attack, clamors strike at their foes with high frequency sonic beams. If cornered or overwhelmed, a clamor uses its sonic burst ability before attempting to flee using its speed of sound ability, which almost always ensures its escape.","ecology":"","habitat_society":""},{"name":"Clockwork Swarm","cr":4,"xp":1200,"alignment":"N","size":"Tiny","type":"construct","subtypes":["swarm"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 natural, +2 size","hp":42,"hd":"4d10+20","hdvalue":4,"hp_mods":["self repair 3 (acid, cold, fire)"],"fort":1,"ref":3,"will":2,"immunities":["construct traits","swarm traits"],"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":40}],"melee":"swarm (1d6)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 12"}],"strength":14,"dexterity":15,"wisdom":13,"charisma":12,"baseatk":4,"skills":[{"skill":"Stealth","value":2,"special":"+6 when not moving"}],"environments":["any"],"organizations":["squad (2-4 swarms)"],"treasure":"none","description_visual":"A mass of tiny insect-like mechanical creatures surges closer.","group":"Clockwork","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Self-Repair","kind":"Ex","details":"A clockwork swarm regains 3 hit points per round. Damage dealt from acid, cold, or fire effects cannot be self-repaired. If a clockwork swarm takes damage from an area attack, it is unable to repair itself for 1d6 rounds following the attack. If reduced to 0 or less hit points, it regains 1 hit point per round (but still cannot repair damage caused by acid, cold, or fire effects) until it has at least 1 hit point (at which time it begins to self-repair at its normal rate of 3 hit points per round)."}],"description":"Clockwork swarms are a collection of tiny, insect-like clockworks that work together as a single creature. An individual member of the swarm poses little threat. Yet when acting in concert, a swarm poses a deadly threat to adventurers. Much like the clockwork warrior, the clockwork swarm forms a fighting frame from random pieces of trash, debris, and other cast-offs. The swarm, however, is much more capable of adapting to new situations and surviving combat. Unless the individual components of the swarm are destroyed, it simply reforms and continues its attack.\n\nArea of effect attacks, such as burning oil, fireball, or lightning bolt are the most effective means of destroying the swarm. A clockwork swarm typically appears as a ramshackle collection of spare parts and garbage draped in a thick, web-like substance and arranged in a vaguely humanoid form.\n\nA swarm prefers to lie in wait and strike from ambush, collecting innocuous looking piles of debris that adventurers overlook as harmless but that the swarm is capable of quickly forming into a combat-worthy frame. If the swarm attempts to assemble itself from a pile of debris, assume that the swarm starts the round with -10 hit points and self-repairs from there.","ecology":"","habitat_society":""},{"name":"Cobalt Viper","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"magical beast","subtypes":["extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["poison (10 ft., DC 17)"],"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+3 Dex, +5 natural","hp":42,"hd":"5d10+15","hdvalue":5,"fort":7,"ref":7,"will":3,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +9 (1d8+1 plus poison)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":17,"constitution":16,"intelligence":2,"wisdom":14,"charisma":10,"baseatk":5,"cmb":6,"cmd":19,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Climb","value":15},{"skill":"Perception","value":11},{"skill":"Stealth","value":11},{"skill":"Swim","value":11}],"environments":["any (Plane of Molten Skies)"],"organizations":["solitary","pair","nest (3-6)"],"treasure":"incidental","description_visual":"This creature appears to be a metallic blue-scaled snake with crystal eyes. Its forked red tongue flicks from its fanged mouth.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 17 Fort; frequency 1/ round for 6 rounds; effect 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Poison Aura","kind":"Ex","details":"A cobalt viper's poison is so potent, that it exudes it in an aura around its body. A creature that starts its turn within the area is subjected to the cobalt viper's poison. The poison from this aura is weaker than its bite however, and deals only 1 point of Con damage (instead of 1d3 Con damage)."}],"description":"Cobalt vipers are poisonous snakes found on the Plane of Molten Skies. Whatever magic transported the Steel Garden to that realm is thought to have brought the vipers here as well. They are indigenous to the Garden and are virtually unknown outside of it.\n\nA cobalt viper appears to be constructed of metal; in fact its scales are actually a composite of the steel found within the Steel Garden and normal snake scales. How exactly these creatures came to exist is unknown. A typical cobalt viper is about 5 ft. long though species up to 12 ft. long or more have been sighted. Cobalt vipers are sometimes hunted by intelligent races for their scales. The scales are taken and fashioned into various pieces of jewelry or used to adorn armor and weapons.\n\nCobalt vipers are highly aggressive predators that prefer to attack from ambush. Normally, a cobalt viper trails its prey allowing its poison aura to sap the target's strength. After its prey is sufficiently weakened, the cobalt viper lunges from its hiding place and strikes.","ecology":"","habitat_society":""},{"name":"Cobra Flower","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"plant","init":1,"senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+1 Dex, +4 natural, -1 size","hp":45,"hd":"6d8+18","hdvalue":6,"fort":8,"ref":3,"will":3,"immunities":["plant traits"],"speed":[{"type":"land","speed":5}],"melee":"bite +6 (1d8+4 plus 1d6 acid and grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d8+4 plus 1d6 acid"}],"strength":17,"dexterity":13,"constitution":16,"wisdom":13,"charisma":9,"baseatk":4,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"can't be tripped","environments":["cold forests","temperate forests"],"organizations":["solitary","patch (2-4)"],"treasure":"none","description_visual":"This tall, slender plant has a large flowering bulb topping its brownish-green roots. Two large green leaves flank its flowering top, giving the appearance of a cobra's hood. Its leaves are thin and have transparent blotches on them.","source":"Tome of Horrors Complete (3pp)","description":"Cobra flowers draw nutrients from sunlight, the soil, and water, but enjoy a diet of insects, rodents, animals, and even humanoids when available. The creatures can be found nesting in forests and often take up residence near small population areas where they can feed on humanoids who wander into their area. Many a child's or adult's disappearance can be attributed to a cobra flower.\n\nWhen a cobra flower detects a living creature, it remains motionless until its prey is within 5 ft. It then spreads its leafy hood, opens its flowery bulb, and bites its prey, secreting acidic enzymes to break down and digest the victim.","ecology":"","habitat_society":""}];
